local function cycleNow() return math.floor(Workspace:GetServerTimeNow() / INTERVAL) end
local function rollStock(items, seed, cycle)
    local rng = Random.new(cycle * 1000 + seed)
    local out = {}
    for _, it in ipairs(items) do
        local n = rng:NextNumber()
        local cnt = rng:NextInteger(it.min or 0, it.max or 0)
        if not it.offsale then out[it.name] = (n <= it.chance) and cnt or 0 end
    end
    return out
end
local function nextStock(items, seed, itemName, lookahead)
    local c0 = cycleNow()
    for c = c0, c0 + (lookahead or 80) do
        local cnt = rollStock(items, seed, c)[itemName]
        if cnt and cnt > 0 then
            return math.max(0, c * INTERVAL - Workspace:GetServerTimeNow()), cnt
        end
    end
    return nil
end
local function fmtTime(s)
    s = math.max(0, math.floor(s or 0))
    if s >= 3600 then return string.format("%dh%dm", math.floor(s/3600), math.floor((s%3600)/60)) end
    if s >= 60   then return string.format("%dm%ds", math.floor(s/60), s%60) end
    return s .. "s"
end

