end
local function selectedProtect()
    local v, set = Opt.rh_protect and Opt.rh_protect.Value, {}
    if type(v) == "table" then for k, val in pairs(v) do if val == true then set[k] = true elseif type(val) == "string" then set[val] = true end end end
    return set
end
local function sellPlan()
    local keep, protect = (Opt.rh_keeptop and Opt.rh_keeptop.Value) or 4, selectedProtect()
    local list = {}
    for id, h in pairs(horsesData()) do list[#list+1] = { id = id, m = tonumber(h.Multiplier) or 0, rarity = h.Rarity } end
    table.sort(list, function(a, b) return a.m > b.m end)
    local toSell = {}
    for i = keep + 1, #list do
        if not protect[list[i].rarity] then toSell[#toSell+1] = list[i].id end
    end
    return toSell, #list
end
