        local sold = 0
        for _, id in ipairs(toSell) do
            if not manual and not on("rh_autosell") then break end
            if not isHorseRacing(id) then
                pcall(function() Net:FireServer("SellHorse", id) end)
                sold = sold + 1; task.wait(0.3)
            end
        end
        if sold > 0 then notify(L["Sold "] .. sold .. L[" horse(s)"]) end
        sellBusy = false
    end)
end

