local function selectedBuyRarities()
    local v, set = Opt.rh_buyeggs and Opt.rh_buyeggs.Value, {}
    if type(v) == "table" then for k, val in pairs(v) do if val == true then set[k] = true elseif type(val)=="string" then set[val]=true end end end
    return set
end
task.spawn(function()
    while RUNNING do
        if on("rh_buyeggs_on") then
            local want, live, c = selectedBuyRarities(), eggStock(), cash()
            for idx, it in ipairs(EGG_ITEMS) do
                if not it.offsale and want[it.rarity] then
                    local cnt = live[it.name]
                    if cnt and cnt > 0 and c >= it.price then pcall(function() Net:Call("PurchaseItem", "Eggs", idx) end); task.wait(0.4) end
                end
            end
        end
        task.wait(3)
    end
end)
task.spawn(function()
    while RUNNING do
        if on("rh_buyfruit_on") then
            local target = (Opt.rh_buyapple and Opt.rh_buyapple.Value) or 0
            if target > 0 and fruitHeld("Apple") < target and cash() >= 150 then
                local a = fruitStock()["Apple"]
                if a == -1 or (a and a > 0) then pcall(function() Net:Call("PurchaseItem", "Fruit", 1) end); task.wait(0.4) end
            end
        end
        task.wait(3)
    end
end)

