local predWinner, predMine = nil, nil
local raceBind = Net:Bind("RaceStart", function(info)
    if type(info) ~= "table" or type(info.Horses) ~= "table" then return end
    local ranked = {}
    for _, h in pairs(info.Horses) do
        ranked[#ranked+1] = { name = h.Name or "?", uid = h.UserId,
                              ft = tonumber(h.FinishTime) or math.huge, fall = (tonumber(h.FallHurdle) or 0) > 0 }
    end
    table.sort(ranked, function(a, b)
        local af, bf = a.fall and 1 or 0, b.fall and 1 or 0
        if af ~= bf then return af < bf end
        return a.ft < b.ft
    end)
    local place, total = nil, #ranked
    for i, r in ipairs(ranked) do if r.uid == lp.UserId then place = i end end
    predWinner = ranked[1] and ranked[1].name or "-"
    predMine = place and string.format("P%d/%d %s", place, total, place == 1 and "WIN" or "lose") or "not racing"
    notify(predWinner .. " wins | you " .. predMine)
end)
local cleanBind = Net:Bind("RaceCleanup", function() predWinner, predMine = nil, nil end)
onClean(function() pcall(function() raceBind:Disconnect() end); pcall(function() cleanBind:Disconnect() end) end)
local function readLeaderboard()
    local pg = lp:FindFirstChild("PlayerGui"); if not pg then return nil end
    local rows = {}
    for _, d in ipairs(pg:GetDescendants()) do
        if d.Name == "RacerTemplate" and d:IsA("GuiObject") and d.Visible then
            local pl, hn = d:FindFirstChild("Place"), d:FindFirstChild("HorseName")
            if pl and hn then
                local pn = d:FindFirstChild("PlayerName")
                rows[#rows+1] = { place = tonumber(tostring(pl.Text):match("%d+")) or 99,
                                  horse = tostring(hn.Text), player = pn and tostring(pn.Text) or "" }
            end
        end
    end
    if #rows == 0 then return nil end
    table.sort(rows, function(a, b) return a.place < b.place end)
    return rows
end
task.spawn(function()
    local myName, myDisp = lp.Name, lp.DisplayName
    while RUNNING do
        if predWinner then
            pcall(function()
                rpWinner:SetText(L["Predicted Winner: "] .. predWinner)
                rpMine:SetText(L["Your horse: "] .. predMine)
            end)
        else
            local rows = readLeaderboard()
            if rows then
                local mine
                for _, r in ipairs(rows) do
                    if r.player:find(myName, 1, true) or r.player:find(myDisp, 1, true) then mine = r; break end
                end
                pcall(function()
                    rpWinner:SetText(L["Leader (live): "] .. rows[1].horse)
                    rpMine:SetText(mine and ("Your horse: P" .. mine.place) or L["Your horse: -"])
                end)
            else
                pcall(function() rpWinner:SetText(L["Predicted Winner: -"]); rpMine:SetText(L["Your horse: -"]) end)
            end
        end
        task.wait(0.5)
    end
end)

