local ServerBox = SetTab:AddLeftGroupbox(L["Server"])
local function httpGet(url)
    local req = (syn and syn.request) or http_request or request
    if req then local ok, r = pcall(req, { Url = url, Method = "GET" }); if ok and type(r)=="table" and r.Body then return r.Body end end
    local ok, r = pcall(function() return game:HttpGet(url) end); if ok then return r end
end
ServerBox:AddButton({ Text = L["Join Emptiest Server"], Func = function()
    task.spawn(function()
        local best, bestJob, cursor = nil, nil, ""
        for _ = 1, 10 do
            local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"):format(game.PlaceId)
            if cursor ~= "" then url = url .. "&cursor=" .. cursor end
            local body = httpGet(url); if not body then break end
            local ok, data = pcall(function() return HttpService:JSONDecode(body) end); if not ok then break end
            for _, s in ipairs(data.data or {}) do
                if type(s.playing) == "number" and s.id ~= game.JobId and s.playing < (s.maxPlayers or 999) then
                    if not best or s.playing < best then best, bestJob = s.playing, s.id end
                end
            end
            if data.nextPageCursor and data.nextPageCursor ~= "" then cursor = data.nextPageCursor else break end
            task.wait(0.15)
        end
        if bestJob then notify(L["Joining server ("] .. tostring(best) .. ")")
            pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, bestJob, lp) end)
        else notify(L["No server found"]) end
    end)
end })

